/* A community's own words on every email it sends (run after part 217): community_email_templates takes the four ticket emails (event_ticket, event_ticket_invite, event_refund, event_cancelled) and the seven emails of a paid plan (membership_started, membership_renewed, membership_renewal_reminder, membership_payment_failed, membership_canceled, membership_plan_changed, membership_ended) beside the welcome, an approved request and an invite, and a button label of up to 40 characters (a new nullable column). The kinds saved before stay allowed, so no row is refused. No row changes. The table stays server only, row level security on, nothing granted to anon or signed in users. Until it runs, Emails › Customer emails › Communities saves the welcome, an approved request and an invite without a button, and says this part is needed for the others. Safe to run again. */
DO $do$ DECLARE c record; BEGIN IF to_regclass('public.community_email_templates') IS NULL THEN RAISE NOTICE 'part 301: community_email_templates is not here yet; run part 217 first, then this again.'; RETURN; END IF; FOR c IN SELECT conname FROM pg_constraint WHERE conrelid = 'public.community_email_templates'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) ILIKE '%kind%' LOOP EXECUTE format('ALTER TABLE public.community_email_templates DROP CONSTRAINT %I', c.conname); END LOOP; ALTER TABLE public.community_email_templates ADD CONSTRAINT community_email_templates_kind_check CHECK (kind IN ('welcome', 'join_approved', 'invite', 'announcement', 'event_reminder', 'course_available', 'event_ticket', 'event_ticket_invite', 'event_refund', 'event_cancelled', 'membership_started', 'membership_renewed', 'membership_renewal_reminder', 'membership_payment_failed', 'membership_canceled', 'membership_plan_changed', 'membership_ended')); ALTER TABLE public.community_email_templates ADD COLUMN IF NOT EXISTS button text; ALTER TABLE public.community_email_templates DROP CONSTRAINT IF EXISTS community_email_templates_button_check; ALTER TABLE public.community_email_templates ADD CONSTRAINT community_email_templates_button_check CHECK (button IS NULL OR char_length(button) <= 40); ALTER TABLE public.community_email_templates ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.community_email_templates FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_email_templates TO service_role; END $do$;
notify pgrst, 'reload schema';
